class ScanError extends Error {
  constructor(message, line, column) {
    super(message);
    this.line = line;
    this.column = column;
  }
}

class Scanner {
  constructor(input) {
    this.input = input;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
  }

  // Get current character without advancing
  current() {
    if (this.pos >= this.input.length) return null;
    return this.input[this.pos];
  }

  // Peek ahead n characters
  peek(n = 1) {
    const pos = this.pos + n;
    if (pos >= this.input.length) return null;
    return this.input[pos];
  }

  // Advance position and track line/column
  advance() {
    if (this.pos >= this.input.length) return null;

    const ch = this.input[this.pos];
    this.pos++;

    if (ch === '\n') {
      this.line++;
      this.column = 1;
    } else if (ch === '\t') {
      // Tab moves to next multiple of 4 plus 1
      // Formula: floor((column + 3) / 4) * 4 + 1
      this.column = Math.floor((this.column + 3) / 4) * 4 + 1;
    } else {
      this.column++;
    }

    return ch;
  }

  // Main scanning function
  scan() {
    while (this.pos < this.input.length) {
      const ch = this.current();

      // Skip whitespace (but not newlines, which we process)
      if (ch === ' ' || ch === '\t' || ch === '\r') {
        this.advance();
        continue;
      }

      if (ch === '\n') {
        this.advance();
        continue;
      }

      // Line comment
      if (ch === '/' && this.peek() === '/') {
        this.scanLineComment();
        continue;
      }

      // Block comment
      if (ch === '/' && this.peek() === '*') {
        this.scanBlockComment();
        continue;
      }

      // String
      if (ch === '"') {
        this.scanString();
        continue;
      }

      // Raw string
      if (ch === 'r' && this.peek() === '"') {
        this.scanRawString();
        continue;
      }

      // Number
      if (ch >= '0' && ch <= '9') {
        this.scanNumber();
        continue;
      }

      // Identifier or keyword
      if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_') {
        this.scanIdentifier();
        continue;
      }

      // Punctuation
      if (this.scanPunctuation()) {
        continue;
      }

      // Unknown character
      throw new ScanError(`unexpected character ${ch}`, this.line, this.column);
    }

    return this.tokens;
  }

  scanLineComment() {
    // Skip // and everything until newline
    this.advance(); // /
    this.advance(); // /
    while (this.current() && this.current() !== '\n') {
      this.advance();
    }
  }

  scanBlockComment() {
    const startLine = this.line;
    const startCol = this.column;

    this.advance(); // /
    this.advance(); // *

    let depth = 1;
    while (depth > 0 && this.pos < this.input.length) {
      if (this.current() === '/' && this.peek() === '*') {
        this.advance();
        this.advance();
        depth++;
      } else if (this.current() === '*' && this.peek() === '/') {
        this.advance();
        this.advance();
        depth--;
      } else {
        this.advance();
      }
    }

    if (depth > 0) {
      throw new ScanError('unterminated block comment', startLine, startCol);
    }
  }

  scanString() {
    const startLine = this.line;
    const startCol = this.column;

    this.advance(); // opening "

    let value = '';
    while (this.current() && this.current() !== '"') {
      if (this.current() === '\n') {
        throw new ScanError('newline in string', this.line, this.column);
      }

      if (this.current() === '\\') {
        const backslashLine = this.line;
        const backslashCol = this.column;
        this.advance();

        if (!this.current()) {
          throw new ScanError('unterminated string', startLine, startCol);
        }

        const escaped = this.current();
        switch (escaped) {
          case 'n':
            value += '\n';
            this.advance();
            break;
          case 't':
            value += '\t';
            this.advance();
            break;
          case 'r':
            value += '\r';
            this.advance();
            break;
          case '\\':
            value += '\\';
            this.advance();
            break;
          case '"':
            value += '"';
            this.advance();
            break;
          case '0':
            value += '\0';
            this.advance();
            break;
          case 'x': {
            this.advance();
            let hex = '';
            for (let i = 0; i < 2; i++) {
              if (!this.current() || !/[0-9a-fA-F]/.test(this.current())) {
                throw new ScanError(`invalid escape \\x`, backslashLine, backslashCol);
              }
              hex += this.current();
              this.advance();
            }
            value += String.fromCharCode(parseInt(hex, 16));
            break;
          }
          case 'u': {
            this.advance();
            if (this.current() !== '{') {
              throw new ScanError(`invalid escape \\u`, backslashLine, backslashCol);
            }
            this.advance();
            let code = '';
            while (this.current() && this.current() !== '}') {
              if (!/[0-9a-fA-F]/.test(this.current())) {
                throw new ScanError(`invalid escape \\u`, backslashLine, backslashCol);
              }
              code += this.current();
              this.advance();
            }
