      this.advance();
      this.advance();
      this.tokens.push({
        kind: 'punct',
        body: twoCharStr,
        line: startLine,
        column: startCol,
      });
      return true;
    }

    // Single-character operators
    const oneCharOps = [
      '+',
      '-',
      '*',
      '/',
      '%',
      '=',
      '<',
      '>',
      '!',
      '(',
      ')',
      '{',
      '}',
      '[',
      ']',
      ',',
      ';',
      '.',
    ];

    if (oneCharOps.includes(this.current())) {
      const text = this.current();
      this.advance();
      this.tokens.push({
        kind: 'punct',
        body: text,
        line: startLine,
        column: startCol,
      });
      return true;
    }

    return false;
  }
}

