              if (!/[0-9a-fA-F]/.test(this.current())) {
                throw new ScanError(`invalid escape \\u`, backslashLine, backslashCol);
              }
              code += this.current();
              this.advance();
            }
            if (!this.current()) {
              throw new ScanError(`invalid escape \\u`, backslashLine, backslashCol);
            }
            this.advance(); // closing }
            const codePoint = parseInt(code, 16);
            if (codePoint > 0x10ffff) {
              throw new ScanError(`invalid escape \\u`, backslashLine, backslashCol);
            }
            value += String.fromCodePoint(codePoint);
            break;
          }
          default:
            throw new ScanError(`invalid escape \\${escaped}`, backslashLine, backslashCol);
        }
      } else {
        value += this.current();
        this.advance();
      }
    }

    if (this.current() !== '"') {
      throw new ScanError('unterminated string', startLine, startCol);
    }

    this.advance(); // closing "

    this.tokens.push({
      kind: 'string',
      body: JSON.stringify(value),
      line: startLine,
      column: startCol,
    });
  }

  scanRawString() {
    const startLine = this.line;
    const startCol = this.column;

    this.advance(); // r
    this.advance(); // opening "

    let value = '';
    while (this.current() && this.current() !== '"') {
      value += this.current();
      this.advance();
    }

    if (this.current() !== '"') {
      throw new ScanError('unterminated string', startLine, startCol);
    }

    this.advance(); // closing "

    this.tokens.push({
      kind: 'rawstring',
      body: JSON.stringify(value),
      line: startLine,
      column: startCol,
    });
  }

  scanNumber() {
    const startLine = this.line;
    const startCol = this.column;
    let text = '';

    // Check for prefixes (hex, binary, octal)
    if (this.current() === '0' && this.peek()) {
      const next = this.peek();
      if (next === 'x' || next === 'X') {
        return this.scanNumberWithPrefix(startLine, startCol, 'hex');
      }
      if (next === 'b' || next === 'B') {
        return this.scanNumberWithPrefix(startLine, startCol, 'binary');
      }
      if (next === 'o' || next === 'O') {
        return this.scanNumberWithPrefix(startLine, startCol, 'octal');
      }
    }

    // Decimal number
    this.scanDecimalNumber(startLine, startCol);
  }

  scanNumberWithPrefix(startLine, startCol, type) {
    let text = '';
    text += this.current(); // 0
    this.advance();
    text += this.current(); // x/b/o
    this.advance();

    const digitRegex =
      type === 'hex'
        ? /[0-9a-fA-F]/
        : type === 'binary'
          ? /[01]/
          : /[0-7]/;

    // Check that there's at least one digit after the prefix
    if (!this.current() || !digitRegex.test(this.current())) {
      // No digit after prefix - error
      if (this.current() && /[a-zA-Z0-9_]/.test(this.current())) {
        text += this.current();
        throw new ScanError(`invalid number ${text}`, startLine, startCol);
      }
      throw new ScanError(`invalid number ${text}`, startLine, startCol);
    }

    // Read digits
    while (this.current() && (digitRegex.test(this.current()) || this.current() === '_')) {
      if (this.current() === '_') {
        // _ must be between two digits
        if (!text || !digitRegex.test(text[text.length - 1])) {
          text += this.current();
          throw new ScanError(`invalid number ${text}`, startLine, startCol);
        }
        if (!this.peek() || !digitRegex.test(this.peek())) {
          text += this.current();
          throw new ScanError(`invalid number ${text}`, startLine, startCol);
        }
      }
      text += this.current();
      this.advance();
    }

    // Check for invalid trailing characters
    if (this.current() && /[a-zA-Z0-9_]/.test(this.current())) {
      text += this.current();
      throw new ScanError(`invalid number ${text}`, startLine, startCol);
    }

    this.tokens.push({
      kind: 'number',
      body: text,
      line: startLine,
      column: startCol,
    });
  }

  scanDecimalNumber(startLine, startCol) {
    let text = '';

    // Read integer part
    while (this.current() && (/[0-9]/.test(this.current()) || this.current() === '_')) {
      if (this.current() === '_') {
        // _ must be between two digits
        if (!text || !/[0-9]/.test(text[text.length - 1])) {
          text += this.current();
          throw new ScanError(`invalid number ${text}`, startLine, startCol);
        }
        if (!this.peek() || !/[0-9]/.test(this.peek())) {
          text += this.current();
          throw new ScanError(`invalid number ${text}`, startLine, startCol);
        }
      }
      text += this.current();
      this.advance();
    }

    // Check for decimal point
    if (this.current() === '.' && this.peek() && /[0-9]/.test(this.peek())) {
      text += this.current();
      this.advance();

      // Read fractional part
      while (this.current() && (/[0-9]/.test(this.current()) || this.current() === '_')) {
        if (this.current() === '_') {
          // _ must be between two digits
          if (!text || !/[0-9]/.test(text[text.length - 1])) {
            text += this.current();
            throw new ScanError(`invalid number ${text}`, startLine, startCol);
          }
          if (!this.peek() || !/[0-9]/.test(this.peek())) {
            text += this.current();
            throw new ScanError(`invalid number ${text}`, startLine, startCol);
          }
        }
        text += this.current();
        this.advance();
      }
    }

    // Check for exponent
    if (this.current() && /[eE]/.test(this.current())) {
      const next = this.peek();
      // Exponent requires a digit or a sign followed by a digit
      let hasValidExponent = false;
      if (next && /[0-9]/.test(next)) {
        hasValidExponent = true;
      } else if (next && /[+-]/.test(next) && this.peek(2) && /[0-9]/.test(this.peek(2))) {
        hasValidExponent = true;
      }

      if (hasValidExponent) {
        text += this.current();
        this.advance();

        if (this.current() && /[+-]/.test(this.current())) {
          text += this.current();
          this.advance();
        }

        // Read exponent digits
        while (this.current() && (/[0-9]/.test(this.current()) || this.current() === '_')) {
          if (this.current() === '_') {
            // _ must be between two digits
            if (!text || !/[0-9]/.test(text[text.length - 1])) {
              text += this.current();
              throw new ScanError(`invalid number ${text}`, startLine, startCol);
            }
            if (!this.peek() || !/[0-9]/.test(this.peek())) {
              text += this.current();
              throw new ScanError(`invalid number ${text}`, startLine, startCol);
            }
          }
          text += this.current();
          this.advance();
        }
      }
    }

    // Check for invalid trailing characters
    if (this.current() && /[a-zA-Z0-9_]/.test(this.current())) {
      text += this.current();
      throw new ScanError(`invalid number ${text}`, startLine, startCol);
    }

    this.tokens.push({
      kind: 'number',
      body: text,
      line: startLine,
      column: startCol,
    });
  }

  scanIdentifier() {
    const startLine = this.line;
    const startCol = this.column;
    let text = '';

    while (this.current() && (/[a-zA-Z0-9_]/.test(this.current()))) {
      text += this.current();
      this.advance();
    }

    const keywords = new Set([
      'let',
      'if',
      'else',
      'while',
      'return',
      'true',
      'false',
      'null',
    ]);

    const kind = keywords.has(text) ? 'keyword' : 'ident';

    this.tokens.push({
      kind,
      body: text,
      line: startLine,
      column: startCol,
    });
  }

  scanPunctuation() {
    const startLine = this.line;
    const startCol = this.column;

    // Two-character operators (matched longest first)
    const twoCharOps = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>'];
    const twoCharStr = this.current() + (this.peek() || '');
    if (twoCharOps.includes(twoCharStr)) {
      this.advance();
      this.advance();
      this.tokens.push({
        kind: 'punct',
        body: twoCharStr,
        line: startLine,
        column: startCol,
      });
      return true;
    }

    // Single-character operators
    const oneCharOps = [
      '+',
      '-',
      '*',
      '/',
      '%',
      '=',
      '<',
      '>',
      '!',
      '(',
      ')',
      '{',
      '}',
      '[',
      ']',
      ',',
      ';',
      '.',
    ];

    if (oneCharOps.includes(this.current())) {
      const text = this.current();
      this.advance();
      this.tokens.push({
        kind: 'punct',
        body: text,
        line: startLine,
        column: startCol,
      });
      return true;
    }

    return false;
  }
}

export { Scanner, ScanError };
"}

