{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { Scanner, ScanError } from './scanner.js';

const args = process.argv.slice(2);

// Check usage
if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js tokens|stats\n');
  process.exit(2);
}

const mode = args[0];

// Read stdin
let input = '';
const stdin = process.stdin;

stdin.setEncoding('utf8');

// Synchronously read all input
stdin.on('data', (chunk) => {
  input += chunk;
});

stdin.on('end', () => {
  try {
    const scanner = new Scanner(input);
    const tokens = scanner.scan();

    if (mode === 'tokens') {
      // Output: <line>:<column> <kind> <body>
      for (const token of tokens) {
        process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`);
      }
    } else if (mode === 'stats') {
      // Output: <kind> <count> for each kind, then total
      const counts = {
        ident: 0,
        keyword: 0,
        number: 0,
        punct: 0,
        rawstring: 0,
        string: 0,
      };

      for (const token of tokens) {
        counts[token.kind]++;
      }

      const kinds = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string'];
      for (const kind of kinds) {
        process.stdout.write(`${kind} ${counts[kind]}\n`);
      }

      const total = tokens.length;
      process.stdout.write(`total ${total}\n`);
    }

    process.exit(0);
  } catch (error) {
    if (error instanceof ScanError) {
      process.stderr.write(
        `error: ${error.line}:${error.column}: ${error.message}\n`
      );
      process.exit(2);
    } else {
      throw error;
    }
  }
});
"}

